<?php
namespace App\Http\Controllers\Admin;
use App\Enums\ShortlistStatus;use App\Http\Controllers\Controller;use App\Models\CustomerRequirement;use App\Models\Worker;use App\Models\WorkerShortlist;use App\Services\ActivityLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class WorkerShortlistController extends Controller { public function index(Request $request):View{$items=WorkerShortlist::with(['requirement.customer','requirement.service','worker'])->when($request->filled('status'),fn($q)=>$q->where('status',$request->input('status')))->latest('shortlisted_at')->paginate(20)->withQueryString();return view('admin.shortlists.index',['items'=>$items,'statuses'=>ShortlistStatus::cases()]);} public function store(Request $request,CustomerRequirement $requirement,Worker $worker,ActivityLogger $logger):RedirectResponse{abort_unless($request->user()->hasPermission('worker-shortlists.manage'),403);$item=WorkerShortlist::firstOrCreate(['customer_requirement_id'=>$requirement->id,'worker_id'=>$worker->id],['shortlisted_by'=>$request->user()->id,'shortlisted_at'=>now(),'status'=>ShortlistStatus::Shortlisted]);if($item->wasRecentlyCreated){if($requirement->requirement_status->value==='open'){$requirement->update(['requirement_status'=>'shortlisted','updated_by'=>$request->user()->id]);$requirement->statusHistory()->create(['old_status'=>'open','new_status'=>'shortlisted','changed_by'=>$request->user()->id,'reason'=>'Worker shortlisted']);}$logger->log('shortlisted','worker-shortlists',$item,'Worker shortlisted.',['requirement_code'=>$requirement->requirement_code,'worker_code'=>$worker->worker_code]);return back()->with('success','Worker shortlisted.');}return back()->with('success','Worker is already on this shortlist.');} public function update(Request $request,WorkerShortlist $shortlist,ActivityLogger $logger):RedirectResponse{abort_unless($request->user()->hasPermission('worker-shortlists.manage'),403);$data=$request->validate(['status'=>['required','in:shortlisted,contacted,interested,not_interested,rejected,selected,removed'],'notes'=>['nullable','string','max:2000']]);$old=$shortlist->status->value;$shortlist->update($data);$logger->log('status_changed','worker-shortlists',$shortlist,'Shortlist status changed.',['from'=>$old,'to'=>$data['status']]);return back()->with('success','Shortlist updated.');} }
